// App icon set. Screens import lucide-style names from here; each one is a
// Phosphor icon (regular weight) so the whole app shares one cleaner style.
// `strokeWidth` >= 2.5 maps to the bold weight; pass `weight` to override.
import {
  AlignBottom as PAlignBottom, AlignCenterHorizontal as PAlignCenterHorizontal, AlignCenterVertical as PAlignCenterVertical, AlignLeft as PAlignLeft, AlignRight as PAlignRight, AlignTop as PAlignTop, Archive as PArchive, ArrowCounterClockwise as PArrowCounterClockwise, ArrowDown as PArrowDown, ArrowDownRight as PArrowDownRight, ArrowElbowDownLeft as PArrowElbowDownLeft, ArrowLeft as PArrowLeft, ArrowLineDown as PArrowLineDown, ArrowRight as PArrowRight, ArrowSquareOut as PArrowSquareOut, ArrowUUpLeft as PArrowUUpLeft, ArrowUUpRight as PArrowUUpRight, ArrowUp as PArrowUp, ArrowUpRight as PArrowUpRight, ArrowsClockwise as PArrowsClockwise, ArrowsLeftRight as PArrowsLeftRight, ArrowsOut as PArrowsOut, Bell as PBell, BellSlash as PBellSlash, Calendar as PCalendar, CalendarBlank as PCalendarBlank, CalendarDots as PCalendarDots, Cards as PCards, CaretDoubleLeft as PCaretDoubleLeft, CaretDoubleRight as PCaretDoubleRight, CaretDown as PCaretDown, CaretLeft as PCaretLeft, CaretRight as PCaretRight, CaretUp as PCaretUp, ChartBar as PChartBar, ChartLine as PChartLine, Check as PCheck, CheckCircle as PCheckCircle, CheckSquare as PCheckSquare, CircleNotch as PCircleNotch, ClipboardText as PClipboardText, Clock as PClock, ClockCountdown as PClockCountdown, CloudSlash as PCloudSlash, Code as PCode, Confetti as PConfetti, Copy as PCopy, Cursor as PCursor, Database as PDatabase, DotsSixVertical as PDotsSixVertical, DotsThree as PDotsThree, DownloadSimple as PDownloadSimple, Eraser as PEraser, Eye as PEye, FileImage as PFileImage, FilePlus as PFilePlus, FileText as PFileText, FileXls as PFileXls, Fire as PFire, Flag as PFlag, FloppyDisk as PFloppyDisk, FlowArrow as PFlowArrow, GearSix as PGearSix, GitBranch as PGitBranch, GridNine as PGridNine, HardDrives as PHardDrives, Highlighter as PHighlighter, HouseSimple as PHouseSimple, Image as PImage, ImageBroken as PImageBroken, Info as PInfo, Key as PKey, Keyboard as PKeyboard, Lifebuoy as PLifebuoy, Link as PLink, List as PList, ListBullets as PListBullets, ListChecks as PListChecks, ListNumbers as PListNumbers, Lock as PLock, LockOpen as PLockOpen, MagicWand as PMagicWand, MagnifyingGlass as PMagnifyingGlass, Minus as PMinus, Monitor as PMonitor, Moon as PMoon, Note as PNote, Palette as PPalette, Pause as PPause, PenNib as PPenNib, PencilSimple as PPencilSimple, PiggyBank as PPiggyBank, Play as PPlay, Plus as PPlus, Printer as PPrinter, PushPin as PPushPin, PushPinSlash as PPushPinSlash, Question as PQuestion, Receipt as PReceipt, Repeat as PRepeat, Scales as PScales, Shapes as PShapes, ShieldCheck as PShieldCheck, SignIn as PSignIn, SignOut as PSignOut, SkipForward as PSkipForward, SlidersHorizontal as PSlidersHorizontal, Sparkle as PSparkle, Square as PSquare, SquaresFour as PSquaresFour, Stack as PStack, StackMinus as PStackMinus, StackPlus as PStackPlus, Star as PStar, Sun as PSun, Target as PTarget, TextAUnderline as PTextAUnderline, TextAlignCenter as PTextAlignCenter, TextAlignLeft as PTextAlignLeft, TextAlignRight as PTextAlignRight, TextB as PTextB, TextItalic as PTextItalic, TextStrikethrough as PTextStrikethrough, TextT as PTextT, TextUnderline as PTextUnderline, Trash as PTrash, TreeStructure as PTreeStructure, UploadSimple as PUploadSimple, User as PUser, UserCircle as PUserCircle, UserPlus as PUserPlus, Wallet as PWallet, Warning as PWarning, WarningCircle as PWarningCircle, X as PX,
  BookOpen as PBookOpen, Bug as PBug, ChatCircleDots as PChatCircleDots, Coins as PCoins, Command as PCommand, EnvelopeSimple as PEnvelopeSimple, GithubLogo as PGithubLogo, Lightning as PLightning, Notebook as PNotebook, RocketLaunch as PRocketLaunch, TrendUp as PTrendUp,
} from "@phosphor-icons/react";

function wrap(Icon, name) {
  function TaskrIcon({ strokeWidth, weight, ...props }) {
    return <Icon weight={weight ?? (strokeWidth >= 2.5 ? "bold" : "regular")} {...props} />;
  }
  TaskrIcon.displayName = name;
  return TaskrIcon;
}

